-- 伦理审批结果同步审计：保留外部批件、状态、有效期及附件路径。
BEGIN;

CREATE TABLE IF NOT EXISTS "项目伦理同步记录" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "外部系统编号" bigint NOT NULL,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "外部审批编号" varchar(150) NOT NULL,
    "状态" varchar(20) NOT NULL,
    "批文编号" varchar(100),
    "批准时间" timestamp without time zone,
    "有效期至" date,
    "批文路径" varchar(1000),
    "外部更新时间" timestamp without time zone,
    "最后同步时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "同步批次号" varchar(100),
    "备注" varchar(1000),
    CONSTRAINT "pk_项目伦理同步记录" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_项目伦理同步_系统" FOREIGN KEY ("外部系统编号") REFERENCES "外部系统"("编号"),
    CONSTRAINT "uq_项目伦理同步_外部审批" UNIQUE ("外部系统编号", "外部审批编号"),
    CONSTRAINT "ck_项目伦理同步_状态" CHECK ("状态" IN ('待审','已批准','有效','已拒绝','已过期','已撤回'))
);

CREATE INDEX IF NOT EXISTS "ix_项目伦理同步_项目" ON "项目伦理同步记录" ("流程模板编号", "项目编号", "状态", "有效期至");

UPDATE "系统迁移版本"
   SET "版本" = 58,
       "脚本" = '001-058',
       "检查摘要" = '增加伦理审批结果同步审计和项目伦理字段回写'
 WHERE "编号" = 1;

COMMIT;
